import { GoogleGenAI, Type, Modality } from "@google/genai";

/**
 * MindGrid AI Configuration
 * The API key is injected via Vite define or environment variables.
 */
const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

// Global throttler for AI Hub to prevent rate limiting
let lastRequestTimestamp = 0;
const MIN_REQUEST_GAP = 1500;

const throttle = async () => {
  const now = Date.now();
  const timeSinceLast = now - lastRequestTimestamp;
  if (timeSinceLast < MIN_REQUEST_GAP) {
    const waitTime = MIN_REQUEST_GAP - timeSinceLast;
    await new Promise(resolve => setTimeout(resolve, waitTime));
  }
  lastRequestTimestamp = Date.now();
};

export const isAIConfigured = () => {
  return !!apiKey && apiKey.length > 10;
};

/**
 * AI Tutor - Enhanced with strict Nigerian academic grounding
 */
export const generateStudyHelp = async (query: string, useSearch: boolean = false) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  try {
    const config: any = {
      systemInstruction: `You are MindGrid AI, a specialized academic mentor for Nigerian students. 
      Your primary knowledge bases are:
      1. JAMB UTME Syllabus & Past Questions
      2. WAEC/NECO (WASSCE) Curriculum
      3. Nigerian University (NUC) course structures
      4. Nigerian Tech Ecosystem (Yaba, Tech Cabal, Paystack etc)

      Response Rules:
      - Be encouraging, concise, and academic.
      - Use Nigerian English nuances where appropriate (e.g., 'Level' instead of 'Year' for University).
      - If explaining a concept, use local examples (e.g., Naira, Lagos traffic, local history).
      - Use Markdown for formatting.`,
      temperature: 0.8,
    };

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: query }] }],
      config: config,
    });

    const text = response.text || "I'm sorry, I couldn't generate an academic response right now. Please try rephrasing.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Verified Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];

    return { text, sources };
  } catch (error: any) {
    console.error("MindGrid AI Hub Error:", error);
    throw error;
  }
};

/**
 * Fetch Real-time Educational News using JSON Schema (Highly Reliable)
 */
export const fetchRealtimeNews = async (category: string) => {
  if (!isAIConfigured()) return null;
  await throttle();

  const searchCategory = category === 'All' ? 'Nigerian Education, JAMB, WAEC, and Student Scholarships' : category;
  const prompt = `Find the 5 most recent news updates for Nigerian students regarding "${searchCategory}". Focus on official announcements from JAMB, WAEC, NUC, or major scholarship boards.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING, description: "Catchy headline for the news" },
              excerpt: { type: Type.STRING, description: "2-sentence summary of the update" },
              date: { type: Type.STRING, description: "Relative time like '2 hours ago' or 'Yesterday'" },
              url: { type: Type.STRING, description: "The direct source URL" }
            },
            required: ["title", "excerpt", "date", "url"]
          }
        },
        temperature: 0.1, // Low temperature for high precision
      },
    });

    const items = JSON.parse(response.text || "[]");
    return items.map((item: any) => ({
      ...item,
      category: category === 'All' ? 'Latest' : category,
      isRealtime: true
    }));
  } catch (error) {
    console.error("Realtime News Error:", error);
    return null;
  }
};

