    const cat = category?.toLowerCase() || 'general';
    const images: Record<string, string[]> = {
      jamb: ['1434030216411-0b793f4b4173', '1516321318423-f06f85e504b3', '1454165833222-d1d44d60ed67'],
      waec: ['1503676260728-1c00da096a0b', '1521587760476-6c120c2d309d', '1546410531-bb4caa6b424d'],
      scholarships: ['1523050335392-93851179ae09', '1541339907198-e08756ebafe3', '1519389950473-47ba0277781c'],
      university: ['1562774053-701939374585', '1523580494863-d97976f990a6', '1492176861649-430f8249a46c'],
      tech: ['1498050108023-c5249f4df085', '1461749280664-7a9d2a7c5c2a', '1550751827-4bd374c3f58b'],
      career: ['1521791136668-7a43f7558f39', '1552664730-d307ca884978', '1517245386807-bb43f82c33c4'],
      general: ['1488190211464-844cb1a1c5b0', '1522202176988-66273c2fd55f', '1491840681634-70a91ae7340d']
    };
    const pool = images[cat] || images['general'];
    const imageId = pool[index % pool.length];
    return `https://images.unsplash.com/photo-${imageId}?auto=format&fit=crop&q=80&w=800`;
  };

  const handleSuggest = async () => {
    if (!suggestionTopic.trim() || isGenerating) return;
    setIsGenerating(true);
    try {
      const newArticle = await generateFullArticle(suggestionTopic);
      if (newArticle) {
        const saved = await saveCuratedArticle(newArticle, user?.email || 'Anonymous Student');
        if (saved) {
          setCuratedArticles(prev => [saved, ...prev]);
          setActiveTab('curated');
          setSuggestionTopic('');
          setSelectedArticle(saved);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const loadData = async () => {
    setIsLoading(true);
    try {
      const [newsData, curatedData] = await Promise.all([
        getNews(activeCategory),
        getCuratedArticles()
      ]);
      setArticles(newsData);
      setCuratedArticles(curatedData);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [activeCategory]);

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="mb-12">
        <SocialBuzzCarousel />
      </div>

      <div className="flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
        <div>
          <div className="flex items-center gap-3 mb-1">
             <h1 className="text-4xl font-black text-slate-800">MindGrid <span className="text-green-600">Library</span></h1>
             <div className="flex bg-slate-100 p-1 rounded-xl">
               <button 
                onClick={() => setActiveTab('live')}
                className={`px-4 py-1.5 text-xs font-black rounded-lg transition-all ${activeTab === 'live' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-400'}`}
               >
                 LIVE NEWS
               </button>
               <button 
                onClick={() => setActiveTab('curated')}
                className={`px-4 py-1.5 text-xs font-black rounded-lg transition-all ${activeTab === 'curated' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-400'}`}
               >
                 AI ARTICLES
               </button>
             </div>
          </div>
          <p className="text-slate-500 font-medium">Deep-dives and real-time updates for Nigerian scholars.</p>
        </div>
        <div className="flex flex-wrap justify-center gap-2">
          {categories.map(cat => (
            <button 
              key={cat} 
              onClick={() => { setActiveCategory(cat); setVisibleCount(5); }}
              className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all ${activeCategory === cat ? 'bg-green-600 text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200'}`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-10">
          {isLoading ? (
            <div className="space-y-8">
              {[1, 2, 3].map(i => <SkeletonArticle key={i} />)}
            </div>
          ) : (
            <div className="space-y-10">
              {activeTab === 'live' ? (
                articles.slice(0, visibleCount).map((post, i) => (
                  <article key={i} className="bg-white rounded-[2rem] overflow-hidden shadow-sm flex flex-col md:flex-row border border-slate-100 group animate-in">
                    <div className="w-full md:w-64 h-52 bg-slate-100 flex-shrink-0 relative overflow-hidden">
                      <img src={getBlogImage(post.category, i)} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={post.category} />
                      <div className="absolute top-4 left-4">
                         <span className="bg-green-600 text-white text-[10px] font-bold px-3 py-1 rounded-full uppercase shadow-lg">{post.category || 'News'}</span>
                      </div>
                    </div>
                    <div className="p-8 flex flex-col justify-center">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{post.date}</span>
                        {post.isRealtime && <i className="fas fa-bolt text-amber-400 text-xs"></i>}
                      </div>
                      <h2 className="text-2xl font-black text-slate-800 mb-3 leading-tight group-hover:text-green-600 transition-colors">{cleanText(post.title)}</h2>
                      <p className="text-slate-500 text-sm leading-relaxed line-clamp-3 mb-6 font-medium">{cleanText(post.excerpt)}</p>
                      <a href={post.url} target="_blank" className="inline-flex items-center gap-3 text-green-600 font-black text-xs uppercase tracking-widest hover:translate-x-1 transition-all">
                        Read Source <i className="fas fa-arrow-right text-[10px]"></i>
                      </a>
                    </div>
                  </article>
                ))
              ) : (
                curatedArticles.filter(a => activeCategory === 'All' || a.category === activeCategory).map((post, i) => (
                  <article key={i} onClick={() => setSelectedArticle(post)} className="bg-white rounded-[2rem] overflow-hidden shadow-sm flex flex-col md:flex-row border border-slate-100 group animate-in cursor-pointer hover:border-green-300 transition-all">
                    <div className="w-full md:w-64 h-52 bg-slate-50 flex-shrink-0 relative overflow-hidden flex items-center justify-center">
                       <i className="fas fa-brain text-slate-100 text-6xl group-hover:scale-125 transition-transform duration-500"></i>
                       <div className="absolute top-4 left-4">
                         <span className="bg-slate-900 text-white text-[10px] font-bold px-3 py-1 rounded-full uppercase shadow-lg">AI Curated</span>
                      </div>
                    </div>
                    <div className="p-8 flex flex-col justify-center">
                      <div className="flex items-center gap-2 mb-3">
                        <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{new Date(post.created_at).toLocaleDateString()}</span>
                        <span className="text-green-600 text-[10px] font-black uppercase tracking-widest">{post.category}</span>
                      </div>
                      <h2 className="text-2xl font-black text-slate-800 mb-3 leading-tight group-hover:text-green-600 transition-colors">{post.title}</h2>
                      <p className="text-slate-500 text-sm leading-relaxed line-clamp-3 font-medium mb-4">{post.excerpt}</p>
                      <div className="text-[10px] text-slate-400 font-bold uppercase italic">Suggested by: {post.suggested_by}</div>
                    </div>
                  </article>
                ))
              )}
            </div>
          )}
        </div>

        <aside className="space-y-8">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-xl">
             <h3 className="font-black text-xl mb-4">Request a Topic</h3>
             <p className="text-slate-400 text-sm mb-6 font-medium">What should our AI write about next? Suggestions become permanent articles.</p>
             <div className="space-y-3">
               <input 
                 type="text" 
                 placeholder="e.g. How to get FUTA admission" 
                 className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                 value={suggestionTopic}
                 onChange={(e) => setSuggestionTopic(e.target.value)}
               />
               <button 
                onClick={handleSuggest}
                disabled={isGenerating || !suggestionTopic.trim()}
                className="w-full bg-green-600 hover:bg-green-500 text-white font-black py-4 rounded-xl transition-all flex items-center justify-center gap-2 text-xs uppercase tracking-widest disabled:opacity-50"
               >
                 {isGenerating ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                 {isGenerating ? 'GENERATING...' : 'CURATE ARTICLE'}
               </button>
             </div>
          </div>

          <AdPlaceholder slot="sidebar-top" className="h-[250px]" />

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
             <h3 className="text-slate-800 font-black text-lg mb-6 flex items-center gap-2">
               <i className="fas fa-shield-alt text-green-600"></i> AI Verification
             </h3>
             <p className="text-slate-500 text-sm leading-relaxed">
               Every curated article is cross-referenced with official NUC and JAMB documents to ensure Nigerian academic integrity.
             </p>
          </div>
        </aside>
      </div>

      {/* Article Modal */}
      {selectedArticle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in">
          <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-[3rem] overflow-hidden flex flex-col shadow-2xl">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
               <div>
                 <span className="text-green-600 text-xs font-black uppercase tracking-widest">{selectedArticle.category} Deep Dive</span>
                 <h2 className="text-3xl font-black text-slate-800 mt-1">{selectedArticle.title}</h2>
               </div>
               <button onClick={() => setSelectedArticle(null)} className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 transition-colors shadow-sm">
                 <i className="fas fa-times text-xl"></i>
               </button>
             </div>
             <div className="flex-grow overflow-y-auto p-12">
               <div className="prose prose-slate max-w-none prose-h2:font-black prose-h3:text-green-600 prose-p:leading-relaxed prose-p:text-slate-600">
                 <ReactMarkdown remarkPlugins={[remarkGfm]}>
                   {selectedArticle.content}
                 </ReactMarkdown>
               </div>
               <div className="mt-12 pt-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-slate-900 rounded-full flex items-center justify-center text-white">
                      <i className="fas fa-robot text-xs"></i>
                    </div>
                    <div>
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Written by</p>
                      <p className="text-sm font-bold text-slate-800">MindGrid AI Curated Library</p>
                    </div>
                  </div>
                  <button onClick={() => setSelectedArticle(null)} className="bg-slate-900 text-white px-8 py-3 rounded-xl font-bold text-sm">Close Reading</button>
               </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

