import { GoogleGenAI, Type, Modality } from "@google/genai";

/**
 * MindGrid AI Configuration
 * The API key is injected via Vite define or environment variables.
 */
const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

// Global throttler for AI Hub to prevent rate limiting
let lastRequestTimestamp = 0;
const MIN_REQUEST_GAP = 1500;

const throttle = async () => {
  const now = Date.now();
  const timeSinceLast = now - lastRequestTimestamp;
  if (timeSinceLast < MIN_REQUEST_GAP) {
    const waitTime = MIN_REQUEST_GAP - timeSinceLast;
    await new Promise(resolve => setTimeout(resolve, waitTime));
  }
  lastRequestTimestamp = Date.now();
};

export const isAIConfigured = () => {
  return !!apiKey && apiKey.length > 10;
};

/**
 * AI Article Generator - Support for specific topics or random trending ones
 */
export const generateFullArticle = async (topic?: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const prompt = topic 
    ? `Write a comprehensive, 500-word educational article for Nigerian students on the topic: "${topic}". Include an introduction, several subheaders, and a concluding advice section.`
    : `First, identify a trending or highly relevant academic topic for Nigerian students today (JAMB, WAEC, University Life, or Tech Careers). Then, write a comprehensive, 500-word educational article on that topic.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: "You are a professional educational journalist for MindGrid Nigeria. Write in a helpful, structured, and authoritative tone. Use Nigerian contexts (Lagos, Abuja, NUC, JAMB, Naira) and academic terminology correctly. Format the content with Markdown.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            excerpt: { type: Type.STRING, description: "A 2-sentence hook for the article" },
            content: { type: Type.STRING, description: "Full Markdown formatted article body with headers and lists" },
            category: { type: Type.STRING, description: "One of: JAMB, WAEC, University, Tech, Career, Scholarships" }
          },
          required: ["title", "excerpt", "content", "category"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Article Generation Error:", error);
    return null;
  }
};

/**
 * AI Tutor - Enhanced with strict Nigerian academic grounding
 */
export const generateStudyHelp = async (query: string, useSearch: boolean = false) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  try {
    const config: any = {
      systemInstruction: `You are MindGrid AI, a specialized academic mentor for Nigerian students. 
      Your primary knowledge bases are:
      1. JAMB UTME Syllabus & Past Questions
      2. WAEC/NECO (WASSCE) Curriculum
      3. Nigerian University (NUC) course structures
      4. Nigerian Tech Ecosystem (Yaba, Tech Cabal, Paystack etc)

      Response Rules:
      - Be encouraging, concise, and academic.
      - Use Nigerian English nuances where appropriate.
      - If explaining a concept, use local examples.
      - Use Markdown for formatting.`,
      temperature: 0.8,
    };

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: query }] }],
      config: config,
    });

    const text = response.text || "I'm sorry, I couldn't generate an academic response right now.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Verified Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];

    return { text, sources };
  } catch (error: any) {
    console.error("MindGrid AI Hub Error:", error);
    throw error;
  }
};

/**
 * Fetch Real-time Educational News
 */
export const fetchRealtimeNews = async (category: string) => {
  if (!isAIConfigured()) return null;
  await throttle();

  const searchCategory = category === 'All' ? 'Nigerian Education, JAMB, WAEC, and Student Scholarships' : category;
  const prompt = `Find the 5 most recent news updates for Nigerian students regarding "${searchCategory}".`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              excerpt: { type: Type.STRING },
              date: { type: Type.STRING },
              url: { type: Type.STRING }
            },
            required: ["title", "excerpt", "date", "url"]
          }
        },
        temperature: 0.1,
      },
    });

    const items = JSON.parse(response.text || "[]");
    return items.map((item: any) => ({
      ...item,
      category: category === 'All' ? 'Latest' : category,
      isRealtime: true
    }));
  } catch (error) {
    console.error("Realtime News Error:", error);
    return null;
  }
};

/**
 * AI Schedule Generation
 */
export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;
  await throttle();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: `Create a comprehensive 7-day study timetable for a student with this goal: "${goal}".` }] }],
      config: {
        systemInstruction: "You are an expert academic counselor specialized in Nigerian education systems.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              day: { type: Type.STRING },
              sessions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    subject: { type: Type.STRING },
                    topic: { type: Type.STRING }
                  },
                  required: ["subject", "topic"]
                }
              }
            },
            required: ["day", "sessions"]
          }
        },
        temperature: 0.4,
      },
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("AI Schedule Error:", error);
    return null;
  }
};

/**
 * Text-to-Speech
 */
export const textToSpeech = async (text: string) => {
  if (!isAIConfigured()) return null;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Read this: ${text.substring(0, 1000)}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (e) {
    console.error("TTS System Error", e);
    return null;
  }
};

