import { MOCK_NEWS, MOCK_CAREERS, MOCK_BUZZ, MOCK_CURATED_ARTICLES } from '../data/staticData';
import { fetchRealtimeNews } from './geminiService';
import { supabase } from './supabase';

/**
 * MindGrid Data Service
 * Hybrid: Uses AI for real-time news and static fallbacks.
 */

const SIMULATED_DELAY = 600;

export const getNews = async (category: string = 'All') => {
  // Try to fetch real-time news first
  try {
    const realtimeNews = await fetchRealtimeNews(category);
    if (realtimeNews && realtimeNews.length > 0) {
      return realtimeNews;
    }
  } catch (e) {
    console.warn("Falling back to static news due to error:", e);
  }

  // Fallback to static mock data
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));
  if (category === 'All') return MOCK_NEWS;
  return MOCK_NEWS.filter(news => news.category.toLowerCase() === category.toLowerCase());
};

export const getCuratedArticles = async () => {
  try {
    const { data, error } = await supabase
      .from('curated_articles')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    // Combine mock data with DB data for a "ready-made" feel
    const dbArticles = data || [];
    return [...dbArticles, ...MOCK_CURATED_ARTICLES];
  } catch (e) {
    console.error("Failed to fetch curated articles, returning mocks only", e);
    return MOCK_CURATED_ARTICLES;
  }
};

export const saveCuratedArticle = async (article: any, userEmail?: string) => {
  try {
    const { data, error } = await supabase
      .from('curated_articles')
      .insert({
        title: article.title,
        excerpt: article.excerpt,
        content: article.content,
        category: article.category,
        suggested_by: userEmail || 'Anonymous Student',
        image_id: Math.floor(Math.random() * 1000).toString()
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  } catch (e) {
    console.error("Failed to save curated article to Supabase", e);
    // Return a temporary object so the UI can still display it if DB fails
    return { ...article, id: Date.now().toString(), suggested_by: userEmail || 'Anonymous Student', created_at: new Date().toISOString() };
  }
};

export const getCareers = async (query: string = '') => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));
  if (!query) return MOCK_CAREERS;

  const lowerQuery = query.toLowerCase();
  return MOCK_CAREERS.filter(job => 
    job.title.toLowerCase().includes(lowerQuery) || 
    job.company.toLowerCase().includes(lowerQuery) ||
    job.description.toLowerCase().includes(lowerQuery)
  );
};

export const getSocialBuzz = async () => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY / 2));
  return MOCK_BUZZ;
};

import { GoogleGenAI, Type, Modality } from "@google/genai";

/**
 * MindGrid AI Configuration
 */
const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

let lastRequestTimestamp = 0;
const MIN_REQUEST_GAP = 1500;

const throttle = async () => {
  const now = Date.now();
  const timeSinceLast = now - lastRequestTimestamp;
  if (timeSinceLast < MIN_REQUEST_GAP) {
    const waitTime = MIN_REQUEST_GAP - timeSinceLast;
    await new Promise(resolve => setTimeout(resolve, waitTime));
  }
  lastRequestTimestamp = Date.now();
};

export const isAIConfigured = () => {
  return !!apiKey && apiKey.length > 10;
};

/**
 * Helper to extract JSON from AI response text
 */
const parseAIResponse = (text: string) => {
  try {
    // Strip markdown code blocks if present
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanText);
  } catch (e) {
    console.error("Failed to parse AI JSON response", e);
    return null;
  }
};

/**
 * AI Article Generator
 */
export const generateFullArticle = async (topic?: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const prompt = topic 
    ? `Write a comprehensive, 500-word educational article for Nigerian students on the topic: "${topic}". Include an introduction, several subheaders, and a concluding advice section.`
    : `Identify a high-impact trending academic topic for Nigerian students (JAMB, University, or Tech Careers). Then, write a comprehensive 500-word article on that topic.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: "You are a professional educational journalist for MindGrid Nigeria. Tone: Authoritative, helpful, Nigerian-focused. Response MUST be valid JSON.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            excerpt: { type: Type.STRING },
            content: { type: Type.STRING, description: "Full Markdown formatted article body" },
            category: { type: Type.STRING }
          },
          required: ["title", "excerpt", "content", "category"]
        }
      }
    });

    return parseAIResponse(response.text || "{}");
  } catch (error) {
    console.error("Article Generation Error:", error);
    return null;
  }
};

/**
 * AI Tutor
 */
export const generateStudyHelp = async (query: string, useSearch: boolean = false) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  try {
    const config: any = {
      systemInstruction: `You are MindGrid AI, a specialized academic mentor for Nigerian students. 
      Grounding: JAMB, WAEC, NUC, Nigerian Tech. Be encouraging and concise. Use Markdown.`,
      temperature: 0.8,
    };

    if (useSearch) config.tools = [{ googleSearch: {} }];

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: query }] }],
      config: config,
    });

    const text = response.text || "I'm sorry, I couldn't generate an academic response right now.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Verified Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];

    return { text, sources };
  } catch (error: any) {
    console.error("MindGrid AI Hub Error:", error);
    throw error;
  }
};

/**
 * Real-time News
 */
export const fetchRealtimeNews = async (category: string) => {
  if (!isAIConfigured()) return null;
  await throttle();

  const searchCategory = category === 'All' ? 'Nigerian Education News 2024' : `Nigerian ${category} news 2024`;
  const prompt = `Find 5 recent updates for Nigerian students regarding "${searchCategory}".`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              excerpt: { type: Type.STRING },
              date: { type: Type.STRING },
              url: { type: Type.STRING }
            },
            required: ["title", "excerpt", "date", "url"]
          }
        },
      },
    });

    return parseAIResponse(response.text || "[]");
  } catch (error) {
    console.error("Realtime News Error:", error);
    return null;
  }
};

/**
 * AI Schedule
 */
export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;
  await throttle();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: `Create a comprehensive 7-day study timetable for: "${goal}".` }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              day: { type: Type.STRING },
              sessions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    subject: { type: Type.STRING },
                    topic: { type: Type.STRING }
                  },
                  required: ["subject", "topic"]
                }
              }
            }
          }
        }
      },
    });

    return parseAIResponse(response.text || "[]");
  } catch (error) {
    console.error("AI Schedule Error:", error);
    return null;
  }
};

/**
 * TTS
 */
export const textToSpeech = async (text: string) => {
  if (!isAIConfigured()) return null;
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text.substring(0, 1000) }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (e) {
    return null;
  }
};

