);

const LibraryPage: React.FC = () => {
  const { user } = useAuth();
  const [articles, setArticles] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [suggestionTopic, setSuggestionTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [selectedArticle, setSelectedArticle] = useState<any | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [genStatus, setGenStatus] = useState('');

  const categories = ['All', 'JAMB', 'WAEC', 'Scholarships', 'University', 'Tech', 'Career'];

  const handleGenerate = useCallback(async (topic?: string) => {
    if (isGenerating || !isAIConfigured()) return;

    setIsGenerating(true);
    setGenStatus(topic ? `Researching "${topic}"...` : 'AI Discovery in progress...');

    try {
      const newArticle = await generateFullArticle(topic);
      if (newArticle) {
        setGenStatus('Archiving to Library...');
        const saved = await saveCuratedArticle(
          newArticle, 
          topic ? (user?.email || 'Anonymous Student') : 'MindGrid AI'
        );

        if (saved) {
          setArticles(prev => [saved, ...prev]);
          setSuggestionTopic('');
          // Only auto-open if it was a user-requested topic
          if (topic) setSelectedArticle(saved);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
      setGenStatus('');
    }
  }, [isGenerating, user]);

  const loadArticles = async () => {
    setIsLoading(true);
    try {
      const data = await getCuratedArticles();
      setArticles(data);

      // Check for automatic generation (3 times a day = 8 hours interval)
      const lastGen = localStorage.getItem('mindgrid_last_auto_gen');
      const eightHours = 8 * 60 * 60 * 1000;
      if (!lastGen || (Date.now() - parseInt(lastGen)) > eightHours) {
        console.log("Triggering scheduled discovery generation...");
        localStorage.setItem('mindgrid_last_auto_gen', Date.now().toString());
        handleGenerate(); // Fire off a random discovery article
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadArticles();
  }, []);

  const filteredArticles = activeCategory === 'All' 
    ? articles 
    : articles.filter(a => a.category?.toLowerCase() === activeCategory.toLowerCase());

  return (
