      </div>

      {/* Hero Suggestion Area - Redesigned to be more compact */}
      <div className="bg-slate-900 p-8 md:p-10 rounded-[2.5rem] text-white shadow-2xl mb-16 relative overflow-hidden">
         <div className="relative z-10 max-w-4xl mx-auto flex flex-col items-center">
             <div className="text-center mb-6">
               <h2 className="text-2xl font-black mb-2">Grow the Knowledge Base</h2>
               <p className="text-slate-400 text-sm font-medium">Suggest a topic for a deep-dive guide or discover a random AI discovery.</p>
             </div>

             <div className="flex w-full bg-white/5 p-2 rounded-2xl border border-white/10 backdrop-blur-md items-center">
               <input 
                 type="text" 
                 placeholder="Enter a topic (e.g. FUTO admission guide)..." 
                 className="flex-grow bg-transparent px-6 py-3 text-sm focus:outline-none text-white placeholder:text-slate-500"
                 value={suggestionTopic}
                 onChange={(e) => setSuggestionTopic(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleGenerate(suggestionTopic)}
                 disabled={isGenerating}
               />
               <div className="flex gap-1">
                 <button 
                  onClick={() => handleGenerate(suggestionTopic)}
                  disabled={isGenerating || !suggestionTopic.trim()}
                  className="bg-green-600 hover:bg-green-500 text-white font-black px-4 py-3 rounded-xl transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-wider disabled:opacity-50"
