                 </button>
                 <button 
                  onClick={() => handleGenerate()}
                  disabled={isGenerating}
                  className="bg-white/10 hover:bg-white/20 text-white font-black px-3 py-3 rounded-xl transition-all flex items-center justify-center border border-white/10 disabled:opacity-50"
