import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { getAllSubscribers } from '../services/dataService';
import { GoogleGenAI } from '@google/genai';
import ReactMarkdown from 'react-markdown';

const AdminDashboard: React.FC = () => {
  const { user, isAdmin } = useAuth();
  const { showToast } = useToast();
  const [subscribers, setSubscribers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [newsletterBrief, setNewsletterBrief] = useState('');
  const [draft, setDraft] = useState('');
  const [isDrafting, setIsDrafting] = useState(false);
  const [isBroadcasting, setIsBroadcasting] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (isAdmin) {
      loadSubscribers();
    }
  }, [isAdmin]);

  const loadSubscribers = async () => {
    setLoading(true);
    const data = await getAllSubscribers();
    setSubscribers(data);
    setLoading(false);
  };

  const handleGenerateNewsletter = async () => {
    if (!newsletterBrief.trim()) return;
    setIsDrafting(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [{ text: `Draft a professional yet engaging newsletter for Nigerian students based on this brief: "${newsletterBrief}". 
        Include: 
        1. A catchy subject line
        2. A warm greeting
        3. Detailed sections for the news
        4. A "Quote of the week"
        5. Call to action. 
        Use local Nigerian context and student slang appropriately.` }]}],
        config: {
          systemInstruction: "You are the Lead Communications Officer for MindGrid. Your voice is encouraging, authoritative, and very 'Lagos-tech' savvy."
        }
      });
      setDraft(response.text || '');
      showToast('AI Draft ready!', 'success');
    } catch (err) {
      showToast('Failed to generate draft', 'error');
    } finally {
      setIsDrafting(false);
    }
  };

  const handleBroadcast = () => {
    if (!draft) return;
    setIsBroadcasting(true);
    setProgress(0);

    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setIsBroadcasting(false);
          showToast(`Broadcast sent to ${subscribers.length} students!`, 'success');
          return 100;
        }
        return prev + 5;
      });
    }, 150);
  };

  if (!isAdmin) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center p-4">
