  const waCount = subscribers.filter(s => s.platform === 'whatsapp').length;

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 flex flex-col lg:flex-row gap-10">
      {/* Sidebar Info */}
      <aside className="lg:w-1/4 space-y-6">
        <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl">
          <h2 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500 mb-6">Network Status</h2>
          <div className="space-y-6">
            <div className="flex justify-between items-end">
              <div>
                <p className="text-3xl font-black">{subscribers.length}</p>
                <p className="text-[10px] uppercase font-bold text-slate-400">Total Subscribers</p>
              </div>
              <i className="fas fa-users text-2xl text-green-500/20"></i>
            </div>
            <div className="grid grid-cols-2 gap-4 pt-6 border-t border-white/10">
              <div>
                <p className="font-black text-lg">{emailCount}</p>
                <p className="text-[8px] uppercase font-bold text-slate-500">Email</p>
              </div>
              <div>
                <p className="font-black text-lg">{waCount}</p>
                <p className="text-[8px] uppercase font-bold text-slate-500">WhatsApp</p>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
            <i className="fas fa-history text-blue-500"></i> Recent Activity
          </h3>
          <ul className="space-y-3">
            {subscribers.slice(0, 5).map((s, i) => (
              <li key={i} className="text-[10px] flex items-center justify-between text-slate-500">
                <span className="truncate max-w-[120px]">{s.email}</span>
                <span className="bg-slate-50 px-2 py-0.5 rounded text-[8px] uppercase font-black">{s.platform}</span>
              </li>
            ))}
          </ul>
        </div>
      </aside>

      {/* Main Content */}
      <div className="lg:w-3/4 space-y-10">
        <section className="bg-white rounded-[3.5rem] p-8 md:p-12 border border-slate-100 shadow-sm">
          <h1 className="text-3xl font-black text-slate-800 mb-8 flex items-center gap-4">
            Intelligence <span className="text-green-600">Composer</span>
            <span className="bg-green-100 text-green-700 text-[10px] px-3 py-1 rounded-full uppercase tracking-widest">v2.0 Beta</span>
          </h1>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest block ml-2">Content Brief</label>
