                value={newsletterBrief}
                onChange={(e) => setNewsletterBrief(e.target.value)}
              />
            </div>

            <button 
              onClick={handleGenerateNewsletter}
              disabled={isDrafting || !newsletterBrief}
              className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl active:scale-95 disabled:opacity-50 flex items-center gap-2"
