              <div className="border-t border-slate-100 pt-10">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-xl font-black text-slate-800">Draft Preview</h3>
                   <div className="flex gap-2">
                     <button onClick={() => setDraft('')} className="text-slate-400 hover:text-red-500 text-xs font-bold px-3 py-1">Discard</button>
                     <button className="text-green-600 hover:text-green-700 text-xs font-bold px-3 py-1 border border-green-100 rounded-lg">Edit Manually</button>
                   </div>
                </div>
                <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-200 prose prose-slate max-w-none prose-sm">
