                    onClick={handleBroadcast}
                    className="w-full bg-green-600 text-white font-black py-5 rounded-2xl hover:bg-green-700 transition-all shadow-xl shadow-green-200 uppercase text-sm tracking-[0.2em] flex items-center justify-center gap-4 group"
                  >
                    Launch Broadcast <i className="fas fa-paper-plane group-hover:translate-x-1 transition-transform"></i>
                  </button>
                )}
              </div>
            </div>
          )}
