import { MOCK_NEWS, MOCK_CAREERS, MOCK_BUZZ, MOCK_CURATED_ARTICLES } from '../data/staticData';
import { fetchRealtimeNews } from './geminiService';
import { supabase } from './supabase';

/**
 * MindGrid Data Service
 */

const SIMULATED_DELAY = 600;

export const subscribeToNewsletter = async (email: string, interests: string[], platform: string = 'email') => {
  try {
    const { data, error } = await supabase
      .from('newsletter_subscribers')
      .upsert({ 
        email: email.trim().toLowerCase(), 
        interests: interests.length > 0 ? interests : ['General'], 
        platform 
      }, { onConflict: 'email' })
      .select();

    if (error) {
      console.error("Supabase Submission Error:", error);
      return { success: false, error: error.message };
    }

    return { success: true };
  } catch (e: any) {
    console.error("Newsletter Subscription Exception:", e);
    return { success: false, error: e.message || 'Unknown network error' };
  }
};

// Admin Service: Log a new broadcast campaign
export const logBroadcast = async (title: string, content: string, reach: number) => {
  try {
    const { data, error } = await supabase
      .from('broadcast_logs')
      .insert({
        title,
        content,
        reach,
        sent_at: new Date().toISOString()
      })
      .select();
    if (error) throw error;
    return data;
  } catch (e) {
    console.error("Failed to log broadcast", e);
    return null;
  }
};

// Admin Service: Fetch broadcast history
export const getBroadcastHistory = async () => {
  try {
    const { data, error } = await supabase
      .from('broadcast_logs')
      .select('*')
      .order('sent_at', { ascending: false });
    if (error) throw error;
    return data || [];
  } catch (e) {
    console.error("Failed to fetch broadcast history", e);
    return [];
  }
};

// Admin Service: Fetch all subscribers
export const getAllSubscribers = async () => {
  try {
    const { data, error } = await supabase
      .from('newsletter_subscribers')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data || [];
  } catch (e) {
    console.error("Failed to fetch subscribers", e);
    return [];
  }
};

// Admin Service: Fetch registered students
export const getRegisteredStudents = async () => {
  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .order('updated_at', { ascending: false });

    if (error) throw error;
    return data || [];
  } catch (e) {
    console.error("Failed to fetch students", e);
    return [];
  }
};

// Admin Service: Comprehensive Platform Stats
export const getAdminDashboardStats = async () => {
  try {
    const [subscribers, profiles, records, articles] = await Promise.all([
      supabase.from('newsletter_subscribers').select('id', { count: 'exact', head: true }),
      supabase.from('profiles').select('id', { count: 'exact', head: true }),
      supabase.from('cgpa_records').select('id', { count: 'exact', head: true }),
      supabase.from('curated_articles').select('id', { count: 'exact', head: true })
    ]);

    return {
      subscribers: subscribers.count || 0,
      students: profiles.count || 0,
      academicOperations: records.count || 0,
      knowledgeEntries: (articles.count || 0) + MOCK_CURATED_ARTICLES.length
    };
  } catch (e) {
    console.error("Stats Fetch Error:", e);
    return { subscribers: 0, students: 0, academicOperations: 0, knowledgeEntries: 0 };
  }
};

export const getNews = async (category: string = 'All') => {
  try {
    const realtimeNews = await fetchRealtimeNews(category);
    if (realtimeNews && realtimeNews.length > 0) {
      return realtimeNews;
    }
  } catch (e) {
    console.warn("Falling back to static news due to error:", e);
  }

  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));
  if (category === 'All') return MOCK_NEWS;
  return MOCK_NEWS.filter(news => news.category.toLowerCase() === category.toLowerCase());
};

export const getCuratedArticles = async () => {
  try {
    const { data, error } = await supabase
      .from('curated_articles')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    const dbArticles = data || [];
    return [...dbArticles, ...MOCK_CURATED_ARTICLES];
  } catch (e) {
    console.error("Failed to fetch curated articles, returning mocks only", e);
    return MOCK_CURATED_ARTICLES;
  }
};

export const saveCuratedArticle = async (article: any, userEmail?: string) => {
  try {
    const { data, error } = await supabase
      .from('curated_articles')
      .insert({
        title: article.title,
        excerpt: article.excerpt,
        content: article.content,
        category: article.category,
        suggested_by: userEmail || 'Anonymous Student',
        image_id: Math.floor(Math.random() * 1000).toString()
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  } catch (e) {
    console.error("Failed to save curated article to Supabase", e);
    return { ...article, id: Date.now().toString(), suggested_by: userEmail || 'Anonymous Student', created_at: new Date().toISOString() };
  }
};

export const getCareers = async (query: string = '') => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));
  if (!query) return MOCK_CAREERS;

  const lowerQuery = query.toLowerCase();
  return MOCK_CAREERS.filter(job => 
    job.title.toLowerCase().includes(lowerQuery) || 
    job.company.toLowerCase().includes(lowerQuery) ||
    job.description.toLowerCase().includes(lowerQuery)
  );
};

export const getSocialBuzz = async () => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY / 2));
  return MOCK_BUZZ;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { getAllSubscribers, getAdminDashboardStats, logBroadcast, getBroadcastHistory } from '../services/dataService';
import { supabase } from '../services/supabase';
import { GoogleGenAI } from '@google/genai';
import ReactMarkdown from 'react-markdown';

const AdminDashboard: React.FC = () => {
  const { isAdmin } = useAuth();
  const { showToast } = useToast();
  const [subscribers, setSubscribers] = useState<any[]>([]);
  const [history, setHistory] = useState<any[]>([]);
  const [stats, setStats] = useState({
    subscribers: 0,
    students: 0,
    academicOperations: 0,
    knowledgeEntries: 0
  });
  const [loading, setLoading] = useState(true);
  const [isLive, setIsLive] = useState(false);
  const [view, setView] = useState<'ledger' | 'intelligence' | 'history'>('ledger');
  const [searchQuery, setSearchQuery] = useState('');
  const [platformFilter, setPlatformFilter] = useState<'all' | 'email' | 'whatsapp'>('all');

  const [newsletterBrief, setNewsletterBrief] = useState('');
  const [draft, setDraft] = useState('');
  const [isDrafting, setIsDrafting] = useState(false);
  const [isBroadcasting, setIsBroadcasting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [deliveryStatus, setDeliveryStatus] = useState<string[]>([]);

  useEffect(() => {
    if (isAdmin) {
      loadInitialData();

      const channel = supabase
        .channel('admin-pulse')
        .on(
          'postgres_changes', 
          { event: 'INSERT', schema: 'public', table: 'newsletter_subscribers' }, 
          (payload) => {
            setSubscribers(prev => [payload.new, ...prev]);
            setStats(prev => ({ ...prev, subscribers: prev.subscribers + 1 }));
            showToast(`New ${payload.new.platform} node linked!`, 'info');
          }
        )
        .subscribe((status) => {
          setIsLive(status === 'SUBSCRIBED');
        });

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [isAdmin]);

  const loadInitialData = async () => {
    setLoading(true);
    try {
      const [subs, dashboardStats, logs] = await Promise.all([
        getAllSubscribers(),
        getAdminDashboardStats(),
        getBroadcastHistory()
      ]);
      setSubscribers(subs);
      setStats(dashboardStats);
      setHistory(logs);
    } catch (e) {
      showToast('Database synchronization error', 'error');
    } finally {
      setLoading(false);
    }
  };

  const filteredSubscribers = useMemo(() => {
    return subscribers.filter(s => {
      const emailMatch = s.email?.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesPlatform = platformFilter === 'all' || s.platform === platformFilter;
      return emailMatch && matchesPlatform;
    });
  }, [subscribers, searchQuery, platformFilter]);

  const handleGenerateNewsletter = async () => {
    if (!newsletterBrief.trim()) return;
    setIsDrafting(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [{ text: `Draft a professional yet engaging newsletter for Nigerian students based on this brief: "${newsletterBrief}". 
        Include: 
        1. A catchy subject line
        2. A warm greeting
        3. Detailed sections for the news
        4. A "Quote of the week"
        5. Call to action. 
        Use local Nigerian context and student slang appropriately.` }]}],
        config: {
          systemInstruction: "You are the Lead Communications Officer for MindGrid. Your voice is encouraging, authoritative, and very 'Lagos-tech' savvy."
        }
      });
      setDraft(response.text || '');
      showToast('AI Intelligence Draft ready!', 'success');
    } catch (err) {
      showToast('AI Synthesis Failed', 'error');
    } finally {
      setIsDrafting(false);
    }
  };

  const handleBroadcast = async () => {
    if (!draft) return;
    setIsBroadcasting(true);
    setProgress(0);
    setDeliveryStatus([]);

    const total = filteredSubscribers.length;
    if (total === 0) {
      showToast('No active nodes to target!', 'error');
      setIsBroadcasting(false);
      return;
    }

    // Step 1: Log the campaign
    const campaignTitle = draft.split('\n')[0].substring(0, 50) || "Academic Briefing";
    await logBroadcast(campaignTitle, draft, total);

    // Step 2: Simulate delivery to each node
    for (let i = 0; i < total; i++) {
      const sub = filteredSubscribers[i];
      await new Promise(r => setTimeout(r, 100)); // Simulate network latency
      setDeliveryStatus(prev => [...prev, `Node ${sub.email} transmitted via ${sub.platform.toUpperCase()}`]);
      setProgress(Math.round(((i + 1) / total) * 100));
    }

    setTimeout(() => {
      setIsBroadcasting(false);
      showToast(`Intelligence Broadcast completed to ${total} nodes!`, 'success');
      loadInitialData(); // Refresh history
    }, 500);
  };

  const copyForWhatsApp = () => {
    const plainText = draft.replace(/[#*]/g, '');
    navigator.clipboard.writeText(plainText);
    showToast('Formatted for WhatsApp Bulk!', 'success');
  };

  if (!isAdmin) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center p-4">
        <div className="bg-slate-100 w-24 h-24 rounded-full flex items-center justify-center mb-8">
          <i className="fas fa-lock text-slate-300 text-3xl"></i>
        </div>
        <h1 className="text-3xl font-black text-slate-800 mb-2">Unauthorized Access</h1>
        <p className="text-slate-500 text-center max-w-sm font-medium">This terminal is restricted to MindGrid administrators. Access attempts are logged.</p>
      </div>
    );
  }

  return (
    <div className="bg-slate-50 min-h-screen">
      <div className="max-w-7xl mx-auto px-4 py-12 space-y-10">

        {/* Header Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {[
            { label: 'Network Reach', val: stats.subscribers, icon: 'fa-rss', color: 'bg-green-600' },
            { label: 'Registered Students', val: stats.students, icon: 'fa-user-graduate', color: 'bg-blue-600' },
            { label: 'Academic Pulse', val: stats.academicOperations, icon: 'fa-bolt', color: 'bg-amber-500' },
            { label: 'Knowledge Base', val: stats.knowledgeEntries, icon: 'fa-brain', color: 'bg-purple-600' }
          ].map((item, i) => (
            <div key={i} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:shadow-xl transition-all">
              <div className={`${item.color} w-14 h-14 rounded-2xl flex items-center justify-center text-white text-xl shadow-lg shadow-${item.color.split('-')[1]}-200`}>
                <i className={`fas ${item.icon}`}></i>
              </div>
              <div>
                <p className="text-3xl font-black text-slate-800">{loading ? '...' : item.val}</p>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{item.label}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="flex flex-col lg:flex-row gap-10">
          {/* Sidebar Feed */}
          <aside className="lg:w-1/4 space-y-6">
            <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl relative overflow-hidden">
              <div className="flex justify-between items-center mb-6 relative z-10">
                <h2 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500">Live Signal</h2>
