                            <button onClick={copyForWhatsApp} className="text-[10px] font-black uppercase bg-green-50 text-green-600 px-4 py-2 rounded-xl border border-green-100 hover:bg-green-100 transition-all">Copy for WA Bulk</button>
                            <button onClick={() => setDraft('')} className="text-[10px] font-black uppercase text-slate-400 hover:text-red-500 px-4 py-2">Discard</button>
                          </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                          <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-200 prose prose-slate max-w-none shadow-inner max-h-[500px] overflow-y-auto">
                            <ReactMarkdown>{draft}</ReactMarkdown>
                          </div>

                          <div className="bg-slate-900 p-8 rounded-[3rem] text-white flex flex-col">
                            <h4 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-6">Transmission Pulse</h4>
                            {isBroadcasting ? (
                              <div className="flex-grow space-y-6">
                                <div className="space-y-4">
                                  <div className="flex justify-between text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">
                                    <span>Transmitting to {filteredSubscribers.length} Nodes</span>
                                    <span>{progress}%</span>
                                  </div>
                                  <div className="w-full bg-slate-800 h-4 rounded-full overflow-hidden">
                                    <div className="bg-green-600 h-full transition-all duration-300 shadow-[0_0_15px_rgba(22,163,74,0.5)]" style={{ width: `${progress}%` }}></div>
                                  </div>
                                </div>
                                <div className="bg-black/30 p-4 rounded-2xl font-mono text-[10px] text-green-500/80 overflow-y-auto h-[280px] space-y-1">
                                  {deliveryStatus.map((log, i) => (
                                    <div key={i} className="flex gap-2">
                                      <span className="opacity-40">[{i+1}]</span> {log}
                                    </div>
                                  ))}
                                  <div className="animate-pulse">_</div>
                                </div>
                              </div>
                            ) : (
                              <div className="flex-grow flex flex-col items-center justify-center text-center space-y-6">
                                <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center text-slate-700">
                                  <i className="fas fa-broadcast-tower text-3xl"></i>
                                </div>
                                <div>
                                  <p className="text-sm font-bold">Ready for Execution</p>
                                  <p className="text-[10px] text-slate-500 mt-1 uppercase tracking-widest">Targets: {filteredSubscribers.length} Student Nodes</p>
                                </div>
                                <button 
                                  onClick={handleBroadcast}
                                  className="w-full bg-green-600 text-white font-black py-6 rounded-3xl hover:bg-green-700 transition-all shadow-2xl shadow-green-900/40 uppercase text-xs tracking-[0.3em] active:scale-95"
                                >
                                  Execute Broadcast
                                </button>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {view === 'history' && (
                  <div className="space-y-8 animate-in">
                    <h2 className="text-2xl font-black text-slate-800">Broadcast <span className="text-slate-400">Archive</span></h2>
                    <div className="grid grid-cols-1 gap-4">
                      {history.length > 0 ? history.map((log, i) => (
                        <div key={log.id} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 flex justify-between items-center group hover:bg-white hover:shadow-lg transition-all">
                          <div>
                            <p className="text-[10px] font-black uppercase text-slate-400 mb-1">{new Date(log.sent_at).toLocaleString()}</p>
                            <h4 className="font-bold text-slate-800">{log.title}</h4>
                            <p className="text-xs text-slate-500">Distributed to {log.reach} students</p>
                          </div>
                          <div className="flex gap-2">
                            <button onClick={() => { setDraft(log.content); setView('intelligence'); }} className="text-[10px] font-black uppercase bg-white text-slate-400 hover:text-green-600 p-3 rounded-xl border border-slate-100 transition-all">Reuse Draft</button>
                          </div>
                        </div>
                      )) : (
                        <div className="py-20 text-center text-slate-300 font-bold">No previous broadcasts recorded.</div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

