import React, { useState, useEffect } from 'react';
import { GRADE_SCALE_5 } from '../constants';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { supabase } from '../services/supabase';

interface Course {
  id: string;
  name: string;
  unit: number;
  grade: string;
}

const CGPACalculator: React.FC = () => {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [courses, setCourses] = useState<Course[]>([
    { id: '1', name: '', unit: 3, grade: 'A' },
  ]);
  const [cgpa, setCgpa] = useState<number>(0);
  const [totalUnits, setTotalUnits] = useState<number>(0);
  const [totalPoints, setTotalPoints] = useState<number>(0);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSaved, setLastSaved] = useState<string | null>(null);

  useEffect(() => {
    const loadInitialData = async () => {
      if (user) {
        const { data } = await supabase
          .from('cgpa_records')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .single();
        if (data) {
          setCourses(data.courses);
          setLastSaved(new Date(data.created_at).toLocaleTimeString());
          return;
        }
      }
      const saved = localStorage.getItem('mindgrid_local_cgpa');
      if (saved) setCourses(JSON.parse(saved));
    };
    loadInitialData();
  }, [user]);

  useEffect(() => {
    let units = 0;
    let points = 0;
    courses.forEach(c => {
      const gradePoint = GRADE_SCALE_5.find(g => g.grade === c.grade)?.point || 0;
      units += Number(c.unit);
      points += (Number(c.unit) * gradePoint);
    });
    setTotalUnits(units);
    setTotalPoints(points);
    setCgpa(units > 0 ? points / units : 0);
    localStorage.setItem('mindgrid_local_cgpa', JSON.stringify(courses));
  }, [courses]);

  const addCourse = () => setCourses([...courses, { id: Math.random().toString(), name: '', unit: 3, grade: 'A' }]);
  const removeCourse = (id: string) => courses.length > 1 && setCourses(courses.filter(c => c.id !== id));
  const updateCourse = (id: string, field: keyof Course, value: any) => setCourses(courses.map(c => c.id === id ? { ...c, [field]: value } : c));

  const saveToCloud = async () => {
    if (!user) return;
    setIsSyncing(true);
    try {
      await supabase.from('cgpa_records').insert({
        user_id: user.id,
        semester_label: `Semester ${new Date().toLocaleDateString()}`,
        gpa: cgpa,
        units: totalUnits,
        courses: courses
      });
      setLastSaved(new Date().toLocaleTimeString());
      showToast('Record synced to cloud!', 'success');
    } catch (err) {
      showToast('Cloud sync failed.', 'error');
    } finally { setIsSyncing(false); }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 md:py-12">
      <div className="bg-white rounded-[2rem] md:rounded-3xl shadow-xl overflow-hidden border border-slate-100">
        <div className="bg-green-600 p-6 md:p-8 text-white">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
              <h1 className="text-2xl md:text-3xl font-black mb-1">CGPA Calculator</h1>
              <p className="text-xs opacity-90">NUC 5.0 Academic Scale</p>
            </div>
            {user && (
              <button onClick={saveToCloud} disabled={isSyncing} className="bg-white/20 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest backdrop-blur-sm transition-all flex items-center gap-2">
                {isSyncing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-cloud-upload-alt"></i>}
                {isSyncing ? 'Saving' : 'Sync'}
              </button>
            )}
          </div>
        </div>

        <div className="p-4 md:p-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Units</p>
              <p className="text-2xl font-black text-slate-800">{totalUnits}</p>
            </div>
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Points</p>
              <p className="text-2xl font-black text-slate-800">{totalPoints}</p>
            </div>
            <div className="bg-green-50 p-4 rounded-2xl border border-green-100 text-center">
              <p className="text-[10px] font-black text-green-600 uppercase mb-1">CGPA</p>
              <p className="text-4xl font-black text-green-700">{cgpa.toFixed(2)}</p>
            </div>
          </div>

          <div className="space-y-4">
            {courses.map((course) => (
              <div key={course.id} className="bg-slate-50/50 p-4 md:p-4 rounded-2xl border border-slate-100 group animate-in">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
                  <div className="md:col-span-6">
                    <input
                      type="text"
                      placeholder="Course Code"
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-green-500 outline-none"
                      value={course.name}
                      onChange={(e) => updateCourse(course.id, 'name', e.target.value)}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-3 md:col-span-5">
                    <select
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-green-500 outline-none"
                      value={course.unit}
                      onChange={(e) => updateCourse(course.id, 'unit', e.target.value)}
                    >
                      {[1, 2, 3, 4, 5, 6].map(u => <option key={u} value={u}>{u} Unit{u > 1 ? 's' : ''}</option>)}
                    </select>
                    <select
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-black text-green-700 focus:ring-2 focus:ring-green-500 outline-none"
                      value={course.grade}
                      onChange={(e) => updateCourse(course.id, 'grade', e.target.value)}
                    >
                      {GRADE_SCALE_5.map(g => <option key={g.grade} value={g.grade}>{g.grade} ({g.point})</option>)}
                    </select>
                  </div>
                  <div className="md:col-span-1 flex justify-center">
                    <button onClick={() => removeCourse(course.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fas fa-trash-alt"></i></button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <button onClick={addCourse} className="w-full mt-6 bg-slate-100 text-slate-800 py-4 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all flex items-center justify-center gap-2">
            <i className="fas fa-plus"></i> Add Course
          </button>
        </div>
      </div>
    </div>
  );
};

export default CGPACalculator;

import React, { useState, useEffect } from 'react';
import { generateAISchedule } from '../services/geminiService';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../services/supabase';

interface StudySession {
  subject: string;
  topic: string;
}

interface DayPlan {
  day: string;
  sessions: StudySession[];
}

const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const COMMON_SUBJECTS = ['Mathematics', 'English Language', 'Physics', 'Chemistry', 'Biology', 'Economics', 'Government', 'Literature', 'Commerce', 'Financial Accounting', 'CRS/IRS', 'Coding/Tech'];

const TimetablePlanner: React.FC = () => {
  const { user } = useAuth();
  const [timetable, setTimetable] = useState<DayPlan[]>([]);
  const [goal, setGoal] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeTab, setActiveTab] = useState('Monday');

  useEffect(() => {
    const loadTimetable = async () => {
      if (user) {
        const { data } = await supabase.from('timetables').select('*').eq('user_id', user.id).limit(1).single();
        if (data) { setTimetable(data.data); setGoal(data.goal); return; }
      }
      const saved = localStorage.getItem('mindgrid_timetable');
      if (saved) setTimetable(JSON.parse(saved));
      else setTimetable(DAYS.map(d => ({ day: d, sessions: [] })));
    };
    loadTimetable();
  }, [user]);

  const syncToCloud = async (newTimetable: DayPlan[], currentGoal: string) => {
    if (!user) { localStorage.setItem('mindgrid_timetable', JSON.stringify(newTimetable)); return; }
    try { await supabase.from('timetables').upsert({ user_id: user.id, goal: currentGoal, data: newTimetable, updated_at: new Date().toISOString() }, { onConflict: 'user_id' }); }
    catch (e) { console.error(e); }
  };

  const handleAISchedule = async () => {
    if (!goal.trim()) return;
    setIsGenerating(true);
    const result = await generateAISchedule(goal);
    if (result && Array.isArray(result)) { setTimetable(result); syncToCloud(result, goal); }
    setIsGenerating(false);
  };

  const addSession = (day: string) => {
    const updated = timetable.map(d => d.day === day ? { ...d, sessions: [...d.sessions, { subject: 'Mathematics', topic: '' }] } : d);
    setTimetable(updated); syncToCloud(updated, goal);
  };

  const updateSession = (day: string, idx: number, field: keyof StudySession, val: string) => {
    const updated = timetable.map(d => d.day === day ? { ...d, sessions: d.sessions.map((s, i) => i === idx ? { ...s, [field]: val } : s) } : d);
    setTimetable(updated); syncToCloud(updated, goal);
  };

  const removeSession = (day: string, idx: number) => {
    const updated = timetable.map(d => d.day === day ? { ...d, sessions: d.sessions.filter((_, i) => i !== idx) } : d);
    setTimetable(updated); syncToCloud(updated, goal);
  };

  const currentDayPlan = timetable.find(d => d.day === activeTab);

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 md:py-12">
      <div className="flex flex-col gap-6 mb-8 md:mb-12">
        <h1 className="text-3xl md:text-4xl font-black text-slate-800">Study <span className="text-green-600">Planner</span></h1>

        <div className="bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-3xl border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Goal-Based AI Planner</p>
          <div className="flex flex-col sm:flex-row gap-2">
            <input 
              type="text" value={goal} onChange={(e) => setGoal(e.target.value)}
              placeholder="e.g. Pass JAMB Science..."
              className="flex-grow bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-green-500 outline-none"
            />
            <button onClick={handleAISchedule} disabled={isGenerating} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase transition-all flex items-center justify-center gap-2">
              {isGenerating ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>} {isGenerating ? 'Planning' : 'Generate'}
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-3">
          <div className="flex lg:flex-col overflow-x-auto no-scrollbar gap-2 py-2">
            {DAYS.map(day => (
              <button
                key={day} onClick={() => setActiveTab(day)}
                className={`flex-shrink-0 px-5 py-3 md:py-4 md:px-6 rounded-xl md:rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-widest transition-all text-center ${activeTab === day ? 'bg-green-600 text-white shadow-lg shadow-green-200' : 'bg-white text-slate-400 border border-slate-100'}`}
              >
                {day.substring(0, 3)}
              </button>
            ))}
          </div>
        </div>

        <div className="lg:col-span-9">
          <div className="bg-white rounded-[2rem] p-6 md:p-8 border border-slate-100 shadow-sm min-h-[400px]">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-xl md:text-2xl font-black text-slate-800">{activeTab}</h2>
              <button onClick={() => addSession(activeTab)} className="text-green-600 text-[10px] font-black uppercase flex items-center gap-2"><i className="fas fa-plus"></i> Add</button>
            </div>
            <div className="space-y-4">
              {currentDayPlan?.sessions.length === 0 ? (
                <div className="text-center py-16 text-slate-300 font-bold">No sessions.</div>
              ) : (
                currentDayPlan?.sessions.map((session, idx) => (
                  <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-transparent hover:border-green-100 flex flex-col md:flex-row gap-3">
                    <select value={session.subject} onChange={(e) => updateSession(activeTab, idx, 'subject', e.target.value)} className="bg-white border-slate-200 rounded-lg p-2 text-xs font-bold outline-none">
                      {COMMON_SUBJECTS.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                    <input type="text" value={session.topic} onChange={(e) => updateSession(activeTab, idx, 'topic', e.target.value)} placeholder="Topic..." className="flex-grow bg-white border-slate-200 rounded-lg p-2 text-xs outline-none" />
                    <button onClick={() => removeSession(activeTab, idx)} className="text-slate-200 hover:text-red-500 transition-colors self-end md:self-center"><i className="fas fa-trash-alt"></i></button>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TimetablePlanner;

import React, { useState, useEffect } from 'react';
import { subscribeToNewsletter } from '../services/dataService';
import { useToast } from '../context/ToastContext';

interface NewsletterModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const NewsletterModal: React.FC<NewsletterModalProps> = ({ isOpen, onClose }) => {
  const { showToast } = useToast();
  const [email, setEmail] = useState('');
  const [platform, setPlatform] = useState<'email' | 'whatsapp'>('email');
  const [interests, setInterests] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const categories = [
    { id: 'JAMB', label: 'JAMB' },
    { id: 'Scholarships', label: 'Scholarships' },
    { id: 'University', label: 'University' },
    { id: 'Tech', label: 'Tech' },
    { id: 'Career', label: 'Careers' }
  ];

  const toggleInterest = (id: string) => {
    setInterests(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    setIsSubmitting(true);
    try {
      const result = await subscribeToNewsletter(email, interests, platform);
      if (result.success) {
        showToast('You are in the Vault! Welcome.', 'success');
        localStorage.setItem('mindgrid_subscribed', 'true');
        onClose();
      } else {
        showToast(result.error || 'Check your connection.', 'error');
      }
    } catch (err) {
      showToast('Connection error.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-end md:items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-in">
      <div 
        className="bg-white w-full md:max-w-xl md:rounded-[3rem] rounded-t-[2.5rem] overflow-hidden shadow-2xl relative animate-in slide-in-from-bottom md:slide-in-from-bottom-0"
        style={{ animationDuration: '0.4s' }}
      >
        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-6 right-6 w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 transition-all z-20"
        >
          <i className="fas fa-times"></i>
        </button>

        <div className="p-8 md:p-12">
          <div className="text-center mb-8">
            <div className="bg-green-600 w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-xl shadow-green-200">
              <i className="fas fa-paper-plane"></i>
            </div>
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">Join the <span className="text-green-600">Inner Circle</span></h2>
            <p className="text-slate-500 text-sm mt-2 font-medium">Get JAMB alerts, scholarships, and tech jobs first.</p>
          </div>

          <form onSubmit={handleSubscribe} className="space-y-6">
            <div className="flex bg-slate-100 p-1.5 rounded-2xl">
              <button 
                type="button"
                onClick={() => setPlatform('email')}
                className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${platform === 'email' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}
              >
                Email
              </button>
              <button 
                type="button"
                onClick={() => setPlatform('whatsapp')}
                className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${platform === 'whatsapp' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-400'}`}
              >
                WhatsApp
              </button>
            </div>

            <input 
              type={platform === 'email' ? 'email' : 'tel'}
              required
              placeholder={platform === 'email' ? 'Enter your email' : '+234 Phone Number'}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 outline-none focus:ring-4 focus:ring-green-500/10 focus:border-green-500 font-medium text-slate-700"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            <div className="space-y-3">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">I am interested in:</p>
              <div className="flex flex-wrap gap-2">
                {categories.map(cat => (
                  <button
                    key={cat.id}
                    type="button"
                    onClick={() => toggleInterest(cat.id)}
                    className={`px-4 py-2 rounded-full border text-[10px] font-bold uppercase tracking-wider transition-all ${interests.includes(cat.id) ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-500 hover:border-slate-300'}`}
                  >
                    {cat.label}
                  </button>
                ))}
              </div>
            </div>

            <button 
              type="submit"
              disabled={isSubmitting || !email}
              className="w-full bg-green-600 text-white font-black py-5 rounded-2xl hover:bg-green-700 transition-all shadow-xl shadow-green-200 active:scale-95 disabled:opacity-50 uppercase text-xs tracking-[0.2em]"
            >
              {isSubmitting ? <i className="fas fa-spinner fa-spin mr-2"></i> : 'Activate Alerts'}
            </button>

            <p className="text-[9px] text-center text-slate-400 font-medium">Join 24,000+ students. Unsubscribe at any time.</p>
          </form>
        </div>
      </div>
    </div>
  );
};

