        </main>
        <Footer onOpenNewsletter={() => setIsNewsletterOpen(true)} />
        <CookieConsent />
        <NewsletterModal isOpen={isNewsletterOpen} onClose={() => setIsNewsletterOpen(false)} />
      </div>
    </Router>
  );
};

